import json
out = [[0]*30 for _ in range(17)]
shapes = [(3,2),(1,9),(4,14),(8,21)]
pattern = [[0,1,2,3,4],[2],[1,2,3],[0,1,2,3,4],[2]]
for color, left in shapes:
    for dy, dxs in enumerate(pattern):
        for dx in dxs:
            out[7+dy][left+dx] = color
assert len(out)==17 and all(len(row)==30 for row in out)
print(json.dumps(out, separators=(',',':')))
